    this.consumer = consumer;
    this.producers = producers;
    this.running = true;
    this.lock = new Object();
}

// Getter methods
getLog(): String { return this.name; }
getConsumer() { return this.consumer; }
getProducer() { return this.producers; }
isRunning(): boolean { return this.running; }

// Method for stopping the channel
stop() {
    synchronized (lock) {
        this.running = false;
    }
}

// Method for starting the channel
start() {
    synchronized (lock) {
        this.running = true;
    }
}

// Method for cleaning the channel
clean(consumer) {
    synchronized (lock) {
        this.running = false;
        consumer.clean();
    }
}

// Method for monitoring the channel
monitor(consumer) {
    synchronized (lock) {
        this.running = true;
        consumer.monitor();
    }
}
}

