/**
* Reads a signed long value from the stream and returns it.
*
* @param offset the offset of the value to read in the stream
* @return the read value
*/
public long readLong(int offset) {
    byte[] bytes = new byte[8];
    for (int i = 0; i < 8; ++i) {
        if (offset <= 0) {
            break;
        }
        bytes[i] = (byte) readByte(offset);
        --i;
        --offset;
    }
    long value = 0;
    for (byte b : bytes) {
        value = (value << 8) | b & 0xFF;
    }
    return value;
}

