public static int computeUTF8Size(String str, int index, int len) {
    if (str == null) {
        throw new NullPointerException();
    }

    // Check bounds
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IndexOutOfBoundsException();
    }

    return getUTF8Length(str, index, len);
}

private static int getUTF8Length(CharSequence str, int index, int len) {
    int length = 0;
    for (int i = index; i < index + len; i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            length += 1;
        } else if (c > 0x7FF) {
            length += 3;
        } else {
            length += 2;
        }
    }
    return length;
}

