private static String substituteVariables(String value) {
    Matcher matcher = VAR_PATTERN.matcher(value);
    StringBuffer buffer = new StringBuffer();
    while (matcher.find()) {
        String key = matcher.group(1);
        String subst = System.getenv(key);
        if (subst == null) {
            subst = props.getProperty(key);
            if (subst == null) {
                continue;
            }
        }
        matcher.appendReplacement(buffer, subst);
    }
    matcher.appendTail(buffer);
    return buffer.toString();
}

