public JsonObject convertProperties(List<KeyStringValuePair> properties) {

    // Initialize a new JsonObject to store the processed properties
    JsonObject processedProperties = new JsonObject();

    // Iterate over the properties and process each one
    for (KeyStringValuePair property : properties) {
        // If the property value is a collection, convert it to a JsonArray
        if (property.getValue() instanceof Collection) {
            JsonArray array = new JsonArray();
            for (Object value : (Collection<?>) property.getValue()) {
                array.add(value != null ? value.toString() : null);
            }
            processedProperties.add(property.getKey(), array);
        }
        // If the property value is an object, convert it to a JsonObject
        else if (property.getValue() instanceof Map) {
            JsonObject object = new JsonObject();
            for (Map.Entry<String, ?> entry : ((Map<String, ?>) property.getValue()).entrySet()) {
                JsonElement element = convertPropertyValue(entry.getValue());
                object.add(entry.getKey(), element);
            }
            processedProperties.add(property.getKey(), object);
        }
        // If the property value is a primitive value, just add it to the JsonObject
        else {
            processedProperties.addProperty(property.getKey(), property.getValue().toString());
        }
    }

    return processedProperties;
}

private JsonElement convertPropertyValue(Object value) {
    // Handle null values
    if (value == null) {
        return null;
    }

    // Handle primitive values
    if (value instanceof Boolean || value instanceof Number || value instanceof String) {
        return new JsonPrimitive(value.toString());
    }

    // Handle collection values
    if (value instanceof Collection) {
        JsonArray array = new JsonArray();
        for (Object element : (Collection<?>) value) {
            array.add(convertPropertyValue(element));
        }
        return array;
    }

    // Handle map values
    if (value instanceof Map) {
        JsonObject object = new JsonObject();
        for (Map.Entry<String, ?> entry : ((Map<String, ?>) value).entrySet()) {
            JsonElement element = convertPropertyValue(entry.getValue());
            object.add(entry.getKey(), element);
        }
        return object;
    }

    // Handle complex objects
    return new JsonPrimitive(value.toString());
}

