private List<Pair<Integer,Integer>> computeMinimalSeparator(Set<Node> tree, Node node, E e) {
    // If the node is not in the tree, it is not reachable from the source node
    if (!tree.contains(node)) {
        return new ArrayList<>();
    }

    // Compute the weight of the edge connecting the source node to the node
    int weight = this.graph.getEdgeWeight(e.getSource(), node, e);

    // Find the smallest edge connecting the node to a neighbor in the tree
    Node neighbor = tree.stream().filter(n -> n.getNeighbors().contains(node)).findFirst().get();
    int neighborWeight = this.graph.getEdgeWeight(neighbor, node);

    // If the weight of the edge connecting the source node to the node is smaller than the weight of the smallest edge connecting the node to a neighbor in the tree, then the node is not reachable from the source node
    if (weight < neighborWeight) {
        return new ArrayList<>();
    }

    // Otherwise, the node is reachable from the source node and the minimal separator is the edge connecting the source node to the node
    List<Pair<Integer,Integer>> separator = new ArrayList<>();
    separator.add(new Pair<>(e.getSource(), node));

    return separator;
}

private Set<Node> computeShortestPaths(Node source) {
    // Initialize with the source node
    Set<Node> tree = new HashSet<>();
    tree.add(source);

    // Loop over all nodes in the graph
    for (Node node : this.graph.getNodes()) {
        // Compute the shortest path from the source node to the node
        List<Node> path = computeShortestPath(source, node);

        // Add the path to the tree
        if (!path.isEmpty()) {
            tree.addAll(path);
        }
    }

    return tree;
}

private List<Node> computeShortestPath(Node source, Node node) {
    // If the node is the source node or it has already been reached, return the empty path
    if (node.equals(source) || tree.contains(node)) {
        return new ArrayList<>();
    }

    // Compute the weight of the shortest path from the source node to the node
    int weight = this.graph.getEdgeWeight(source, node);

    // Find the smallest edge connecting the source node to a neighbor in the graph
    Node neighbor = this.graph.getNeighbors(source).stream().filter(n -> this.graph.getEdgeWeight(n, node) == weight).findFirst().get();

    // Compute the shortest path from the source node to the neighbor
    List<Node> path = computeShortestPath(source, neighbor);

    // Add the node to the path
    path.add(node);

    return path;
