private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // Check if the subgraph is empty
    if (vertices.isEmpty()) {
        return true;
    }

    // Check if the subgraph consists of only one vertex
    if (vertices.size() == 1) {
        return graph.outgoingEdgesOf(vertices.iterator().next()).isEmpty();
    }

    // Check if the subgraph is a clique by iterating over all possible pairs of vertices
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
