List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the upper bounds for each key
    Map<K, Integer> upperBounds = new HashMap<>();
    for (K key : keys) {
        upperBounds.put(key, 0);
    }

    // Compute the upper bounds for each key
    for (int i = 1; i < keys.size(); i++) {
        K key = keys.get(i);
        K prevKey = keys.get(i - 1);
        int upperBound = upperBounds.get(prevKey) + 1;
        upperBounds.put(key, upperBound);
    }

    // Return the list of upper bounds
    List<Integer> result = new ArrayList<>();
    for (K key : keys) {
        result.add(upperBounds.get(key));
    }
    return result;
}
