    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        // Check if the file is not empty
        if (reader.readLine() != null) {
            // Go through each line in the file
            String line;
            while ((line = reader.readLine()) != null) {
                // Split the line into tokens using the comma as the separator
                String[] tokens = line.split(",");

                // Check if the line contains three tokens (timestamp, start, and end)
                if (tokens.length == 3) {
                    // Parse the tokens into long values
                    long timestamp = Long.parseLong(tokens[0]);
                    long start = Long.parseLong(tokens[1]);
                    long end = Long.parseLong(tokens[2]);

                    // Check if the time range overlaps with any of the time ranges specified
                    if (timeRanges.stream().anyMatch(timeRange -> timeRange.isOverlapping(timestamp, start, end))) {
                        // Add the thread snapshot to the list of thread snapshots
                        threadSnapshots.add(new ThreadSnapshot(timestamp, start, end));
