public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

	// Check if the input file is null
	if (file == null) {
		throw new IllegalArgumentException("Input file cannot be null");
	}

	// Check if the time range list is null or empty
	if (timeRanges == null || timeRanges.isEmpty()) {
		throw new IllegalArgumentException("Time range list cannot be null or empty");
	}

	// Initialize the thread snapshots list
	List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

	// Open the file for reading
	try (FileReader fileReader = new FileReader(file)) {

		// Create a buffered reader to read the file
		BufferedReader bufferedReader = new BufferedReader(fileReader);

		// Read the file line by line
		String line;
		while ((line = bufferedReader.readLine()) != null) {

			// Parse the line
			if (line.startsWith("TIME_BLOCK_START")) {
				// Get the time range from the line
				String dateTime = line.split("TIME_BLOCK_START: ")[1].split(" ")[0];
				long time = DateTime.parse(dateTime).getMillis();
				TimeRange timeRange = new TimeRange(time, time);

				// Check if the time range intersects with the given time ranges
				for (ProfileAnalyzeTimeRange range : timeRanges) {
					if (timeRange.intersects(range)) {
						// Add the time range to the list
						threadSnapshots.add(new ThreadSnapshot(timeRange, null, null));
						break;
					}
				}
			} else if (line.startsWith("THREAD_DATA_START")) {
				// Get the thread ID and priority from the line
				String[] parts = line.split("THREAD_DATA_START: ")[1].split(", ");
				long threadId = Long.parseLong(parts[0]);
				int priority = Integer.parseInt(parts[1]);

				// Check if the thread ID is already in the list
				for (ThreadSnapshot snapshot : threadSnapshots) {
					if (snapshot.getThreadId() == threadId) {
						// Add the priority to the existing snapshot
						snapshot.addPriority(priority);
						break;
					}
				}
			} else if (line.startsWith("TIME_BLOCK_STOP")) {
				// Get the time range from the line
				String dateTime = line.split("TIME_BLOCK_STOP: ")[1].split(" ")[0];
				long time = DateTime.parse(dateTime).getMillis();
				TimeRange timeRange = new TimeRange(time, time);

				// Check if the time range intersects with the given time ranges
				for (ProfileAnalyzeTimeRange range : timeRanges) {
					if (timeRange.intersects(range)) {
						// Add the time range to the list
						threadSnapshots.add(new ThreadSnapshot(timeRange, null, null));
						break;
					}
				}
			}
		}
	}

	// Return the thread snapshots list
	return threadSnapshots;
